/**
 * Create a specific "elix" policy
 */
const policy = window?.trustedTypes?.createPolicy(
    "elix",
    {
        createHTML: (value) => {
            return value;
        }
    }
);

/**
 * Create a truste HTML instance using our CSP policy.
 *
 * @param {string} html
 * @returns {TrustedHTML | string}
 */
export function createTrustedHTML(html) {
    return (policy?.createHTML(html) ?? html);
}

/**
 * Set Elix nonce on each style element contained in content.
 *
 * @param {DocumentFragment} content
 * @returns {void}
 */
export function setNonceOnStyleElements(content) {
  /** @type {any} */ const nonceValue = window?.["elixNonce"];
  if (nonceValue) {
    /** @type {NodeListOf<HTMLElement>} */ const styleElements =
      content.querySelectorAll('style, link[rel="stylesheet"]');
    styleElements.forEach((elem) => {
      elem.nonce = nonceValue;
    });
  }
}